<?php
declare(strict_types=1);
function email_escape(string $value): string {return htmlspecialchars($value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function email_origin(): string {
    $origin=rtrim(getenv('APP_URL')?:'https://repotools.online','/');
    return preg_match('~^https://[^\s<>"\x27]+$~D',$origin)?$origin:'https://repotools.online';
}
function email_button(string $url,string $label): string {
    return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td bgcolor="#27197F" align="center" style="background-color:#27197F;background-image:linear-gradient(#27197F,#27197F);border-radius:10px;mso-padding-alt:15px 20px"><a href="'.email_escape($url).'" style="display:block;padding:15px 20px;background:#27197F;background-image:linear-gradient(#27197F,#27197F);color:#ffffff;-webkit-text-fill-color:#ffffff;font-weight:bold;text-decoration:none;border-radius:10px"><span class="gmail-screen"><span class="gmail-difference">'.email_escape($label).'</span></span></a></td></tr></table>';
}
function email_layout(string $title,string $content): string {
    $logo=email_escape(email_origin().'/img/brand/repotools-horizontal-blanco-1024w.png');$heading=email_escape($title);
    return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only"><meta name="supported-color-schemes" content="light"><title>'.$heading.'</title><style>:root{color-scheme:light only;supported-color-schemes:light}.email-body,.email-shell{background-color:#f5f6fb!important}.email-content{background-color:#ffffff!important;color:#172033!important}.email-heading{color:#27197F!important;-webkit-text-fill-color:#27197F}u+.email-body .gmail-screen{background:#000;mix-blend-mode:screen}u+.email-body .gmail-difference{background:#000;mix-blend-mode:difference}[data-ogsc] .email-content{background-color:#ffffff!important;color:#172033!important}[data-ogsc] .email-heading{color:#27197F!important}@media(prefers-color-scheme:dark){.email-body,.email-shell{background-color:#f5f6fb!important}.email-content{background-color:#ffffff!important;color:#172033!important}.email-heading{color:#27197F!important}}</style></head><body class="email-body" style="margin:0;background:#f5f6fb;color:#172033;color-scheme:light only;font-family:Arial,Helvetica,sans-serif"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" bgcolor="#f5f6fb" class="email-shell" style="background:#f5f6fb;background-image:linear-gradient(#f5f6fb,#f5f6fb)"><tr><td align="center" style="padding:20px 12px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px"><tr><td bgcolor="#27197F" style="background:#27197F;background-image:linear-gradient(#27197F,#27197F);padding:22px;border-radius:14px 14px 0 0"><img src="'.$logo.'" width="180" alt="RepoTools" style="display:block;width:180px;max-width:100%;height:auto;border:0;color:#ffffff;font-size:22px;font-weight:bold"></td></tr><tr><td class="email-content" bgcolor="#ffffff" style="background:#ffffff;background-image:linear-gradient(#ffffff,#ffffff);padding:22px;color:#172033;font-size:15px;line-height:1.6;border-radius:0 0 14px 14px"><h1 class="email-heading" style="-webkit-text-fill-color:#27197F;font-size:23px;line-height:1.3;margin:0 0 16px;color:#27197F">'.$heading.'</h1>'.$content.'</td></tr><tr><td style="padding:16px 8px;text-align:center;font-size:12px;line-height:1.6;color:#626b7a">RepoTools · Escaneá, organizá y gestioná tu stock.<br>No compartas tus enlaces de acceso o verificación.</td></tr></table></td></tr></table></body></html>';
}
